o=Original.Fresh();c=AICF_MatchController.For(o);capturedContext=c;o.m_State.OnApply=()=>capturedContext.m_USSRState=new AICF_FactionState();check(!c.AICF_BackgroundConfigureOne(o)&&o.m_State.Writes==1&&c.CloseCalls==0,"opposite faction state swap callback");check(!c.AICF_BackgroundAbortOwned("stale epoch")&&c.CloseCalls==0,"same controller successor epoch never closed");return n;}}
public static class MusterExecute {public static int Run(){int n=0;Action<bool,string>check=(b,s)=>{if(!b)throw new Exception(s);n++;};var o=Original.Fresh();o.m_Slot.Posture="INFANTRY_MUSTER";o.m_Slot.Desired=10;check(o.m_Slot.IsRecruitingInfantry()&&!o.m_Slot.HasActiveRecruitmentOrder(),"native initial waiting posture without order");o.m_State.ApplyCommanderConfiguration(6,0,AICF_EGroupUnitType.INFANTRY,1);check(o.m_Slot.IsRecruitingInfantry(),"actual desired setter does not clear waiting posture");
o=Original.Fresh();o.m_Slot.Posture="INFANTRY_MUSTER";o.m_Slot.Desired=10;var c=AICF_MatchController.For(o);check(c.AICF_BackgroundConfigureOne(o)&&o.m_State.Writes==1&&c.m_OrderPlanner.RefreshCalls==1&&o.m_Slot.m_bInfantryMusterComplete&&!o.m_Slot.IsRecruitingInfantry()&&o.m_Slot.GetWaypoint()!=null&&c.CloseCalls==0,"actual one-of-one planner completion");
o=Original.Fresh();o.m_Slot.Posture="INFANTRY_MUSTER";c=AICF_MatchController.For(o);c.m_USFaction=null;check(!c.AICF_BackgroundConfigureOne(o)&&c.CloseCalls==1&&c.m_OrderPlanner.RefreshCalls==0,"missing exact faction");
o=Original.Fresh();o.m_Slot.Posture="INFANTRY_MUSTER";c=AICF_MatchController.For(o);c.m_OrderPlanner.FailOrder=true;check(!c.AICF_BackgroundConfigureOne(o)&&c.CloseCalls==1&&c.m_OrderPlanner.RefreshCalls==1,"normal handoff cannot create order");
o=Original.Fresh();o.m_Slot.Posture="INFANTRY_MUSTER";c=AICF_MatchController.For(o);c.m_InfantryRecruitment.Queued=true;check(!c.AICF_BackgroundConfigureOne(o)&&o.m_State.Writes==0&&c.m_OrderPlanner.RefreshCalls==0,"pending order never bypassed");
o=Original.Fresh();o.m_Slot.Posture="INFANTRY_MUSTER";c=AICF_MatchController.For(o);c.m_OrderPlanner.OnRefresh=()=>AICF_MatchController.Active=new AICF_MatchController();check(!c.AICF_BackgroundConfigureOne(o)&&c.m_OrderPlanner.RefreshCalls==1&&c.CloseCalls==0&&AICF_MatchController.Active.CloseCalls==0,"handoff callback owner swap");
o=Original.Fresh();o.m_Slot.Posture="INFANTRY_MUSTER";c=AICF_MatchController.For(o);var context=c;c.m_OrderPlanner.OnRefresh=()=>context.m_USSRState=new AICF_FactionState();check(!c.AICF_BackgroundConfigureOne(o)&&c.m_OrderPlanner.RefreshCalls==1&&c.CloseCalls==0,"handoff callback epoch swap");
o=Original.Fresh();o.m_Slot.Posture="INFANTRY_MUSTER";o.m_Slot.Desired=2;check(!o.m_Slot.CompleteInfantryMusterIfReady()&&!o.m_Slot.m_bInfantryMusterComplete,"actual incomplete roster cannot forge completion");return n;}}
public static class Execute {public static int Run(){int n=0;Action<bool,string>check=(b,s)=>{if(!b)throw new Exception(s);n++;};var r=new AICF_InfantryRecruitmentService();check(Original.Fresh().IsCurrent(true,r),"positive");var initial=Original.Fresh();initial.m_Slot.Desired=10;check(initial.IsCurrent(false,r),"before setup permits unchanged desired10");
Action<Action<Original>,string>negative=(change,label)=>{var o=Original.Fresh();change(o);check(!o.IsCurrent(true,r),label);};
negative(o=>o.m_State.Slot=new AICF_GroupSlot(),"slot swap");negative(o=>o.m_Slot.Generation++,"generation");negative(o=>o.m_Group.Id++,"group id");negative(o=>o.m_Group.Rpl="changed","group rpl");negative(o=>o.m_Actor.Id++,"actor id");negative(o=>o.m_Actor.Rpl="changed","actor rpl");negative(o=>o.m_Slot.Desired=2,"desired");negative(o=>o.m_Slot.Ready=false,"readiness");negative(o=>o.m_Slot.Active=true,"active recruitment");negative(o=>o.m_Slot.Recruiting=true,"waiting recruitment");negative(o=>o.m_Group.Count=2,"already recruited second actor");negative(o=>o.m_Group.AliveCount=0,"missing live actor");negative(o=>o.m_Actor.Alive=false,"dead actor");negative(o=>o.m_Actor.AI=false,"human");negative(o=>o.m_Actor.Authoritative=false,"proxy actor");negative(o=>o.m_Group.Authoritative=false,"proxy group");negative(o=>o.m_Group.Faction.Key="USSR","faction");negative(o=>o.m_Slot.Unit=AICF_EGroupUnitType.MOTORIZED_LIGHT,"unit type");negative(o=>o.m_Group.Agents.Clear(),"actual roster empty");negative(o=>o.m_Agent.Actor=new ChimeraCharacter(),"controlled entity");negative(o=>o.m_Agent.Group=new SCR_AIGroup(),"parent group");negative(o=>((ChimeraCharacter)o.m_Actor).Control.Agent=new AIAgent(),"native control swap");
r.Queued=true;check(!Original.Fresh().IsCurrent(true,r),"queued native recruitment");r.Queued=false;Replication.Server=false;check(!Original.Fresh().IsCurrent(true,r),"client");Replication.Server=true;
check(Census.SnapshotComplete(100,100,0,true,80,80,90,90),"complete census");check(Census.SnapshotComplete(4096,4096,0,true,80,80,90,90),"bounded boundary");check(!Census.SnapshotComplete(4097,4096,0,true,80,80,90,90),"truncated");check(!Census.SnapshotComplete(100,99,0,true,80,80,90,90),"not all examined");check(!Census.SnapshotComplete(100,100,1,true,80,80,90,90),"missing agent");check(!Census.SnapshotComplete(100,100,0,false,80,80,90,90),"groups truncated");check(!Census.SnapshotComplete(100,100,0,true,80,81,90,90),"native active changed");check(!Census.SnapshotComplete(100,100,0,true,80,80,90,91),"native intended changed");check(!Census.SnapshotComplete(-1,-1,0,true,80,80,90,90),"unknown count");check(!Census.SnapshotComplete(100,100,0,true,-1,-1,90,90),"unknown native active");check(!Census.SnapshotComplete(100,100,0,true,80,80,-1,-1),"unknown intended");return n;}}
}
'@
Add-Type -TypeDefinition $code.Replace('__BODY_CURRENT__',$current).Replace('__BODY_COMPLETE__',$complete).Replace('__BODY_OWNER__',$owner).Replace('__BODY_STATE__',$state).Replace('__BODY_ABORT__',$abort).Replace('__BODY_CONFIGURE__',$configure).Replace('__BODY_EPOCH__',$epoch).Replace('__BODY_HANDOFF__',$handoff).Replace('__BODY_WAITING__',$waiting).Replace('__BODY_RECRUITING__',$recruiting).Replace('__BODY_MUSTER__',$muster).Replace('__BODY_REFRESH__',$refresh).Replace('__BODY_CARPROOF__',$carProof).Replace('__BODY_WORLDCOMPLETE__',$worldComplete)
$actual=[AICFBackgroundActual.Execute]::Run()+[AICFBackgroundActual.OwnerExecute]::Run()+[AICFBackgroundActual.MusterExecute]::Run()+[AICFBackgroundActual.CarProof]::Run();$checks+=$actual
$scratch=[IO.Path]::GetFullPath((Join-Path $RepositoryRoot ('.codex-runtime/multi-background-contract-'+[guid]::NewGuid().ToString('N'))))
[void][IO.Directory]::CreateDirectory($scratch)
try{
 $metadata='background_mode=MINIMUM_BACKGROUND_CAPACITY preparation_only=1 original_stress_covered=0 normal_campaign=0 '
 $lines=New-Object 'System.Collections.Generic.List[string]';$ledger=''
 foreach($side in 0..1){$faction=@('US','USSR')[$side];foreach($slot in 6..9){$actor=10000+$side*100+$slot;$ledger+="$faction/${slot}:$actor;"}}
 foreach($stage in @('SETUP','FINAL')){
  foreach($side in 0..1){$faction=@('US','USSR')[$side];foreach($slot in 6..9){$actor=10000+$side*100+$slot;$lines.Add("[MULTI_BACKGROUND_MEMBER] ${metadata}stage=$stage faction=$faction numeric_slot=$slot group=$($actor+1000) actor=$actor actor_rpl=$actor same_original_alive_one=1 desired=1 generation=1 physical_agents=1 alive_agents=1 recruiting=0 queued_order=0")}}
  $lines.Add("[MULTI_BACKGROUND_READBACK] ${metadata}stage=$stage t_ms=1000 background_originals=8 missing=0 total_managed_slots=20 selected_groups=12 selected_crew=5 background_originals_id=[$ledger]")
 }
 foreach($trigger in @('SETUP','COHORT')){$lines.Add("[MULTI_BACKGROUND_CENSUS] ${metadata}trigger=$trigger readonly=1 actor_rows_emitted=0 maximum_agents_examined=4096 maximum_groups_examined=4096 agents_returned=100 agents_examined=100 missing=0 groups_complete=1 snapshot_complete=1 native_active_before=100 native_active_after=100 counted_activated=100 native_intended_before=90 native_intended_after=90 native_count_reconciled=1 active_characters=90 active_vehicles=5 active_group_controllers=5 active_null=0 active_other=0")}
 $positive=$lines -join "`r`n"
 $cases=@(,@('positive',$positive,0))
 foreach($mutation in @(
  @('original_stress_covered=0','original_stress_covered=1'),@('same_original_alive_one=1','same_original_alive_one=0'),
  @('desired=1','desired=10'),@('physical_agents=1','physical_agents=2'),@('alive_agents=1','alive_agents=0'),
  @('recruiting=0','recruiting=1'),@('queued_order=0','queued_order=1'),@('missing=0','missing=1'),
  @('total_managed_slots=20','total_managed_slots=12'),@('selected_crew=5','selected_crew=1'),
  @('native_active_after=100','native_active_after=101'),@('native_intended_after=90','native_intended_after=91'),
  @('agents_returned=100','agents_returned=4097'),@('agents_examined=100','agents_examined=99'),
  @('active_vehicles=5','active_vehicles=6'),@('background_originals_id=[US/6:10006;','background_originals_id=[US/6:99999;')
 )){$cases+=,@($mutation[0],$positive.Replace($mutation[0],$mutation[1]),1)}
 $cases+=,@('final actor changed',$positive.Replace('stage=FINAL faction=US numeric_slot=6 group=11006 actor=10006','stage=FINAL faction=US numeric_slot=6 group=11006 actor=99999'),1)
 $cases+=,@('final stage absent',$positive.Replace('stage=FINAL','stage=PERIODIC'),1)
 foreach($case in $cases){$case[1]|Set-Content (Join-Path $scratch 'console.log');& 'C:/Windows/System32/WindowsPowerShell/v1.0/powershell.exe' -NoProfile -ExecutionPolicy Bypass -File (Join-Path $RepositoryRoot 'tests/log-audits/Test-VehicleMultiBackgroundLog.ps1') -LogPath (Join-Path $scratch 'console.log') -EvidenceRoot $scratch *> (Join-Path $scratch 'audit.txt');if($LASTEXITCODE -ne $case[2]){throw "Background log case failed: $($case[0])`n$([IO.File]::ReadAllText((Join-Path $scratch 'audit.txt')))"};$checks++}
}finally{
 $allowed=[IO.Path]::GetFullPath((Join-Path $RepositoryRoot '.codex-runtime')).TrimEnd('\')+'\'
 if(!$scratch.StartsWith($allowed,[StringComparison]::OrdinalIgnoreCase)){throw 'Scratch cleanup outside workspace evidence root'}
 Remove-Item -LiteralPath $scratch -Recurse -Force
}
